syntax:
```c++
template <class T, class Deleter = std::default_delete<T>>
class unique_ptr {
public:
  unique_ptr(T* ptr, Deleter d) : ptr_(ptr), deleter_(d) {}
  ~unique_ptr() { deleter_(ptr_); }
  // ... other members ...
private:
  T* ptr_;
  Deleter deleter_;
};
```

**Implementation Notes:** The compiler generates code for the destructor (`~unique_ptr`) that calls the provided deleter.  If the deleter is a simple function pointer, the compiler might inline the call, significantly improving performance.  However, for more complex deleters (e.g., functors with member variables or complex logic), inlining might be less effective or impossible.  The compiler's optimization capabilities will play a crucial role in determining the final performance.

code_example:
#include <iostream>
#include <memory>
#include <string>
struct MyResource {
  std::string data;
  MyResource(const std::string& d) : data(d) { std::cout << "Resource acquired: " << data << std::endl; }
  ~MyResource() { std::cout << "Resource released: " << data << std::endl; }
};
void customDeleter(MyResource* ptr) {
  std::cout << "Custom deleter releasing: " << ptr->data << std::endl;
  delete ptr;
}
int main() {
  auto ptr1 = std::make_unique<MyResource>("Resource 1");
  auto ptr2 = std::unique_ptr<MyResource, void(*)(MyResource*)>(new MyResource("Resource 2"), customDeleter);
  return 0;
}
